   344	            "#{} {} (~{} chars{})",
   345	            entry.entry_id, entry.label, entry.approx_chars, reason
   346	        ));
   347	    }
   348	    let joined = segments.join("; ");
   349	    format!(
   350	        "Context cleaner removed {} item(s) (~{} chars): {joined}",
   351	        outcome.removed_entries.len(),
   352	        pretty_print_chars(total_chars)
   353	    )
   354	}
