   424	    entries: Vec<HistoryEntry>,
   425	    formatted: String,
   426	    entry_map: HashMap<usize, HistoryEntry>,
   427	}
   428	
   429	impl HistoryView {
   430	    fn build(history: &[ResponseItem], cfg: &ContextCleanerConfig) -> Self {
   431	        let start = history.len().saturating_sub(cfg.max_history_items);
   432	        let tail_guard_start = history.len().saturating_sub(cfg.protected_tail_items);
   433	        let shell_calls = collect_shell_calls(history);
   434	
   435	        let mut entries = Vec::new();
   436	        for (idx, item) in history.iter().enumerate().skip(start) {
   437	            let mut entry = describe_entry(idx, item, &shell_calls, cfg.max_item_bytes);
   438	            let tail_protected = idx >= tail_guard_start
   439	                && !matches!(entry._kind, CleanerEntryKind::ShellOutput { .. });
   440	            if tail_protected {
   441	                entry.removal_allowed = false;
   442	                entry.notes.push("tail-protected".to_string());
   443	            }
   444	            entries.push(entry);
   445	        }
   446	
   447	        let mut formatted_entries = Vec::with_capacity(entries.len());
   448	        let mut entry_map = HashMap::with_capacity(entries.len());
   449	        for entry in &entries {
   450	            entry_map.insert(entry.entry_id, entry.clone());
   451	            formatted_entries.push(format_entry(entry));
   452	        }
   453	
   454	        Self {
   455	            entries,
   456	            formatted: formatted_entries.join("\n\n"),
   457	            entry_map,
   458	        }
   459	    }
   460	
   461	    fn has_actionable_entries(&self) -> bool {
   462	        self.entries.iter().any(|entry| entry.removal_allowed)
   463	    }
   464	}
