   467	struct ShellFunctionArgs {
   468	    #[serde(default)]
   469	    command: Vec<String>,
   470	}
   471	
   472	fn collect_shell_calls(history: &[ResponseItem]) -> HashMap<String, String> {
   473	    let mut map = HashMap::new();
   474	    for item in history {
   475	        match item {
   476	            ResponseItem::LocalShellCall {
   477	                call_id: Some(call_id),
   478	                action: LocalShellAction::Exec(exec),
   479	                ..
   480	            } => {
   481	                map.insert(call_id.clone(), format_shell_command(&exec.command));
   482	            }
   483	            ResponseItem::FunctionCall {
   484	                name,
   485	                arguments,
   486	                call_id,
   487	                ..
   488	            } if name == "shell" => {
   489	                let command = serde_json::from_str::<ShellFunctionArgs>(arguments)
   490	                    .map(|args| format_shell_command(&args.command))
   491	                    .unwrap_or_else(|_| arguments.clone());
   492	                map.insert(call_id.clone(), command);
   493	            }
   494	            _ => {}
   495	        }
   496	    }
   497	    map
   498	}
   499	
   500	fn format_shell_command(parts: &[String]) -> String {
   501	    if parts.is_empty() {
   502	        "<empty command>".to_string()
   503	    } else {
   504	        parts.join(" ")
   505	    }
   506	}
   507	
   508	fn describe_entry(
   509	    entry_id: usize,
   510	    item: &ResponseItem,
   511	    shell_calls: &HashMap<String, String>,
   512	    max_item_bytes: usize,
   513	) -> HistoryEntry {
   514	    match item {
   515	        ResponseItem::Message { role, content, .. } => {
   516	            let text = content_items_to_text(content).unwrap_or_default();
   517	            let approx_chars = text.len();
   518	            let (snippet, truncated_tokens) = truncate_middle(&text, max_item_bytes);
   519	            let _kind = if role == "user" {
   520	                CleanerEntryKind::UserMessage
   521	            } else {
   522	                CleanerEntryKind::AssistantMessage
   523	            };
   524	            HistoryEntry {
   525	                entry_id,
   526	                label: format!("{role} message"),
   527	                snippet,
   528	                approx_chars,
   529	                truncated_tokens,
   530	                removal_allowed: false,
   531	                _kind,
   532	                notes: Vec::new(),
   533	            }
   534	        }
   535	        ResponseItem::LocalShellCall {
   536	            call_id,
   537	            status,
   538	            action,
   539	            ..
   540	        } => {
   541	            let command = match action {
   542	                LocalShellAction::Exec(exec) => format_shell_command(&exec.command),
   543	            };
   544	            let mut notes = vec![format!("status: {status:?}")];
   545	            if call_id.is_none() {
   546	                notes.push("missing call_id; paired output may be unavailable".to_string());
   547	            }
   548	            HistoryEntry {
   549	                entry_id,
   550	                label: format!("shell call `{command}`"),
   551	                snippet: command.clone(),
   552	                approx_chars: command.len(),
   553	                truncated_tokens: None,
   554	                removal_allowed: false,
   555	                _kind: CleanerEntryKind::ShellCall { _command: command },
   556	                notes,
   557	            }
   558	        }
   559	        ResponseItem::FunctionCallOutput { call_id, output } => {
   560	            let text = output.content.clone();
   561	            let approx_chars = text.len();
   562	            let (snippet, truncated_tokens) = truncate_middle(&text, max_item_bytes);
   563	            if let Some(command) = shell_calls.get(call_id) {
   564	                HistoryEntry {
   565	                    entry_id,
   566	                    label: format!("shell output for `{command}`"),
   567	                    snippet,
   568	                    approx_chars,
   569	                    truncated_tokens,
   570	                    removal_allowed: true,
   571	                    _kind: CleanerEntryKind::ShellOutput {
   572	                        _command: command.clone(),
   573	                    },
   574	                    notes: Vec::new(),
   575	                }
   576	            } else {
   577	                HistoryEntry {
   578	                    entry_id,
   579	                    label: format!("tool output (call_id={call_id})"),
   580	                    snippet,
   581	                    approx_chars,
   582	                    truncated_tokens,
   583	                    removal_allowed: false,
   584	                    _kind: CleanerEntryKind::ToolOutput {
   585	                        _name: call_id.clone(),
   586	                    },
   587	                    notes: vec!["non-shell output".to_string()],
   588	                }
   589	            }
   590	        }
   591	        ResponseItem::FunctionCall {
   592	            name, arguments, ..
   593	        } => {
   594	            let (snippet, truncated_tokens) = truncate_middle(arguments, max_item_bytes);
   595	            HistoryEntry {
   596	                entry_id,
   597	                label: format!("tool call `{name}`"),
   598	                snippet,
   599	                approx_chars: arguments.len(),
   600	                truncated_tokens,
   601	                removal_allowed: false,
   602	                _kind: CleanerEntryKind::ToolCall {
   603	                    _name: name.clone(),
   604	                },
   605	                notes: Vec::new(),
   606	            }
   607	        }
   608	        ResponseItem::CustomToolCall { name, input, .. } => {
   609	            let (snippet, truncated_tokens) = truncate_middle(input, max_item_bytes);
   610	            HistoryEntry {
   611	                entry_id,
   612	                label: format!("custom tool call `{name}`"),
   613	                snippet,
   614	                approx_chars: input.len(),
   615	                truncated_tokens,
   616	                removal_allowed: false,
   617	                _kind: CleanerEntryKind::ToolCall {
   618	                    _name: name.clone(),
   619	                },
   620	                notes: Vec::new(),
   621	            }
   622	        }
   623	        ResponseItem::CustomToolCallOutput { call_id, output } => {
   624	            let (snippet, truncated_tokens) = truncate_middle(output, max_item_bytes);
   625	            HistoryEntry {
   626	                entry_id,
   627	                label: format!("custom tool output (call_id={call_id})"),
   628	                snippet,
   629	                approx_chars: output.len(),
   630	                truncated_tokens,
   631	                removal_allowed: false,
   632	                _kind: CleanerEntryKind::ToolOutput {
   633	                    _name: call_id.clone(),
   634	                },
   635	                notes: Vec::new(),
   636	            }
   637	        }
   638	        ResponseItem::Reasoning { summary, .. } => {
   639	            let mut buffer = String::new();
   640	            for item in summary {
   641	                match item {
   642	                    ReasoningItemReasoningSummary::SummaryText { text } => {
   643	                        let _ = writeln!(&mut buffer, "{text}");
   644	                    }
   645	                }
   646	            }
   647	            let (snippet, truncated_tokens) = truncate_middle(&buffer, max_item_bytes);
   648	            HistoryEntry {
   649	                entry_id,
   650	                label: "assistant reasoning".to_string(),
   651	                snippet,
   652	                approx_chars: buffer.len(),
   653	                truncated_tokens,
   654	                removal_allowed: false,
   655	                _kind: CleanerEntryKind::Other,
   656	                notes: Vec::new(),
   657	            }
   658	        }
   659	        _ => HistoryEntry {
   660	            entry_id,
   661	            label: format!("{} item", std::any::type_name::<ResponseItem>()),
   662	            snippet: String::new(),
   663	            approx_chars: 0,
   664	            truncated_tokens: None,
   665	            removal_allowed: false,
   666	            _kind: CleanerEntryKind::Other,
   667	            notes: vec!["unsupported entry type".to_string()],
   668	        },
   669	    }
   670	}
   671	
   672	fn format_entry(entry: &HistoryEntry) -> String {
   673	    let removable = if entry.removal_allowed { "yes" } else { "no" };
   674	    let mut lines = Vec::new();
   675	    lines.push(format!(
   676	        "[{}] {} | removable: {} | chars: {}",
   677	        entry.entry_id, entry.label, removable, entry.approx_chars
   678	    ));
   679	    if let Some(tokens) = entry.truncated_tokens {
   680	        lines.push(format!("note: truncated (~{tokens} tokens removed)"));
   681	    }
   682	    if !entry.notes.is_empty() {
   683	        lines.push(format!("notes: {}", entry.notes.join(", ")));
   684	    }
   685	    if entry.snippet.trim().is_empty() {
   686	        lines.push("snippet: (none)".to_string());
   687	    } else {
   688	        lines.push("snippet:".to_string());
   689	        lines.push(entry.snippet.clone());
   690	    }
   691	    lines.join("\n")
   692	}
   693	
   694	fn usage_below_threshold(usage_percent: Option<f64>, minimum: f32) -> bool {
   695	    match usage_percent {
   696	        Some(percent) => percent < f64::from(minimum),
   697	        None => minimum > 0.0,
   698	    }
   699	}
   700	fn normalize_summary(summary: String) -> Option<String> {
   701	    let trimmed = summary.trim();
   702	    if trimmed.is_empty() {
   703	        None
   704	    } else if trimmed.len() == summary.len() {
   705	        Some(summary)
   706	    } else {
   707	        Some(trimmed.to_string())
   708	    }
   709	}
